INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'character', 'n.', '/ˈkærɪktə/', '性格;品质;角色;(剧中)人物', 'My grandfather has a gentle character and rarely loses his temper.', '我爷爷性格温和,很少发脾气。', 'Family Matters', 1, 0, 'senior', 'wordlist', 'required1', 'U3', 'a gentle character', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'approach', 'v.', '/əˈprəʊtʃ/', '走近;靠近;接近', 'As Father''s birthday approached, we secretly began to plan a surprise.', '随着父亲的生日临近,我们悄悄开始策划一个惊喜。', 'Family Matters', 2, 0, 'senior', 'wordlist', 'required1', 'U3', 'as the day approached', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'chat', 'n.', '/tʃæt/', '闲谈;聊天', 'I had a long chat with my dad about my future.', '我和爸爸就我的未来长谈了一次。', 'Family Matters', 3, 0, 'senior', 'wordlist', 'required1', 'U3', 'have a chat', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'focus', 'v.', '/ˈfəʊkəs/', '(把……)集中(于);专注', 'My brother wants to focus on his music after he leaves school.', '我哥哥想在毕业后专注于他的音乐。', 'Family Matters', 4, 0, 'senior', 'wordlist', 'required1', 'U3', 'focus on', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'career', 'n.', '/kəˈrɪə/', '职业;事业', 'Father hopes I will choose a career in law like him.', '父亲希望我像他一样选择法律方面的职业。', 'Family Matters', 5, 0, 'senior', 'wordlist', 'required1', 'U3', 'a career in music', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'lawyer', 'n.', '/ˈlɔːjə/', '律师', 'My father is a lawyer and helps many people every day.', '我父亲是律师,每天帮助许多人。', 'Family Matters', 6, 0, 'senior', 'wordlist', 'required1', 'U3', 'become a lawyer', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'assume', 'v.', '/əˈsjuːm/', '假定;假设;认为', 'Dad simply assumes that I want to be a lawyer too.', '爸爸想当然地以为我也想当律师。', 'Family Matters', 7, 0, 'senior', 'wordlist', 'required1', 'U3', 'assume that', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'respect', 'v.', '/rɪˈspekt/', '尊敬;敬重', 'Children should respect their parents'' opinions, even when they disagree.', '孩子应当尊重父母的意见,即便意见不同。', 'Family Matters', 8, 0, 'senior', 'wordlist', 'required1', 'U3', 'respect one''s parents', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'studio', 'n.', '/ˈstjuːdiəʊ/', '(音乐)录音室', 'My brother dreams of working in a music studio one day.', '我哥哥梦想着有一天能在录音室工作。', 'Family Matters', 9, 0, 'senior', 'wordlist', 'required1', 'U3', 'a music studio', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'court', 'n.', '/kɔːt/', '法院;法庭', 'Lawyers like my father often work in a court.', '像我父亲这样的律师常常在法庭工作。', 'Family Matters', 10, 0, 'senior', 'wordlist', 'required1', 'U3', 'work in a court', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'ignore', 'v.', '/ɪɡˈnɔː/', '忽视;不理会', 'Try not to ignore your grandfather''s kind advice.', '尽量不要忽视你爷爷善意的建议。', 'Family Matters', 11, 0, 'senior', 'wordlist', 'required1', 'U3', 'ignore advice', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'professional', 'adj.', '/prəˈfeʃ(ə)nəl/', '职业的;专业的', 'He wants to become a professional musician, not a lawyer.', '他想成为一名职业音乐人,而不是律师。', 'Family Matters', 12, 0, 'senior', 'wordlist', 'required1', 'U3', 'a professional musician', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'suit', 'v.', '/suːt/', '适合', 'I am sure a career in music suits my talents.', '我确信音乐方面的职业适合我的天赋。', 'Family Matters', 13, 0, 'senior', 'wordlist', 'required1', 'U3', 'suit one''s talents', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'talent', 'n.', '/ˈtælənt/', '天赋;才能', 'Everyone in my family has a different talent.', '我家每个人都有不同的天赋。', 'Family Matters', 14, 0, 'senior', 'wordlist', 'required1', 'U3', 'a special talent', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'option', 'n.', '/ˈɒpʃ(ə)n/', '选择;可选择的东西', 'Going to university gives me two options for my future.', '上大学给了我未来的两个选择。', 'Family Matters', 15, 0, 'senior', 'wordlist', 'required1', 'U3', 'two options', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'curtain', 'n.', '/ˈkɜːtn/', '(舞台上的)幕;帷幕;窗帘', 'When the curtain fell, our little family play was over.', '幕布落下时,我们的小小家庭话剧就结束了。', 'Family Matters', 16, 0, 'senior', 'wordlist', 'required1', 'U3', 'the curtain falls', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'generation', 'n.', '/ˌdʒenəˈreɪʃ(ə)n/', '一代(人)', 'Three generations of my family live happily under one roof.', '我家三代人幸福地住在同一个屋檐下。', 'Family Matters', 17, 0, 'senior', 'wordlist', 'required1', 'U3', 'three generations', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'gap', 'n.', '/ɡæp/', '差距;差别;缺口', 'There is sometimes a gap between parents and their children.', '父母与子女之间有时会有代沟。', 'Family Matters', 18, 0, 'senior', 'wordlist', 'required1', 'U3', 'the generation gap', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'currently', 'adv.', '/ˈkʌrəntli/', '现时;当前', 'My sister is currently studying at a university far from home.', '我姐姐目前在一所离家很远的大学学习。', 'Family Matters', 19, 0, 'senior', 'wordlist', 'required1', 'U3', 'currently studying', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'regularly', 'adv.', '/ˈreɡjʊləli/', '经常;定期地', 'We visit Grandma regularly on Sunday afternoons.', '我们每周日下午都定期去看望奶奶。', 'Family Matters', 20, 0, 'senior', 'wordlist', 'required1', 'U3', 'visit regularly', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'responsible', 'adj.', '/rɪˈspɒnsɪb(ə)l/', '负责的;负有责任的', 'My elder brother is responsible and helps with the housework.', '我哥哥很有责任心,会帮忙做家务。', 'Family Matters', 21, 0, 'senior', 'wordlist', 'required1', 'U3', 'be responsible for', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'memory', 'n.', '/ˈmem(ə)ri/', '记忆;回忆', 'This old photo brings back a lovely family memory.', '这张旧照片勾起了一段美好的家庭回忆。', 'Family Matters', 22, 0, 'senior', 'wordlist', 'required1', 'U3', 'a lovely memory', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'nowadays', 'adv.', '/ˈnaʊədeɪz/', '现今;现时', 'Nowadays my dad has a beard and looks quite different.', '如今我爸爸留着胡子,看起来很不一样。', 'Family Matters', 23, 0, 'senior', 'wordlist', 'required1', 'U3', 'nowadays', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'jaw', 'n.', '/dʒɔː/', '下巴;下颌', 'My father has always had a strong square jaw.', '我父亲一直有着结实的方下巴。', 'Family Matters', 24, 0, 'senior', 'wordlist', 'required1', 'U3', 'a square jaw', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'beard', 'n.', '/bɪəd/', '胡须', 'Dad has grown a grey beard since I last saw him.', '自上次见面以来,爸爸留起了灰白的胡子。', 'Family Matters', 25, 0, 'senior', 'wordlist', 'required1', 'U3', 'grow a beard', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'skin', 'n.', '/skɪn/', '皮肤;皮', 'My mother still has smooth skin and straight black hair.', '我妈妈依然皮肤光滑、有着乌黑的直发。', 'Family Matters', 26, 0, 'senior', 'wordlist', 'required1', 'U3', 'smooth skin', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'jogging', 'n.', '/ˈdʒɒɡɪŋ/', '慢跑锻炼', 'Mum goes jogging every morning to stay fit.', '妈妈每天早上去慢跑以保持健康。', 'Family Matters', 27, 0, 'senior', 'wordlist', 'required1', 'U3', 'go jogging', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'slim', 'adj.', '/slɪm/', '苗条的;修长的', 'Jogging has kept my mother slim and healthy.', '慢跑使我妈妈保持苗条和健康。', 'Family Matters', 28, 0, 'senior', 'wordlist', 'required1', 'U3', 'stay slim', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'cheek', 'n.', '/tʃiːk/', '面颊;脸颊', 'As a child I had cute rosy cheeks.', '小时候我有可爱的红润脸颊。', 'Family Matters', 29, 0, 'senior', 'wordlist', 'required1', 'U3', 'rosy cheeks', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'nation', 'n.', '/ˈneɪʃ(ə)n/', '国家;民族', 'Family Day is celebrated by families across the whole nation.', '家庭日是全国各地的家庭共同庆祝的节日。', 'Family Matters', 30, 0, 'senior', 'wordlist', 'required1', 'U3', 'across the nation', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'aim', 'v.', '/eɪm/', '力求达到;旨在', 'The festival aims to bring family members closer together.', '这个节日旨在让家庭成员更亲近。', 'Family Matters', 31, 0, 'senior', 'wordlist', 'required1', 'U3', 'aim to do', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'issue', 'n.', '/ˈɪʃuː/', '议题;(争论的)问题', 'We talked openly about the family issues that worried us.', '我们坦诚地谈论了令我们担忧的家庭问题。', 'Family Matters', 32, 0, 'senior', 'wordlist', 'required1', 'U3', 'family issues', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'theme', 'n.', '/θiːm/', '主题', 'The theme of the day was the importance of family love.', '这一天的主题是家庭之爱的重要性。', 'Family Matters', 33, 0, 'senior', 'wordlist', 'required1', 'U3', 'the theme of the day', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'observe', 'v.', '/əbˈzɜːv/', '庆祝;过(节日、生日等);观察', 'Many families observe this special day every May.', '许多家庭每年五月都会庆祝这个特别的日子。', 'Family Matters', 34, 0, 'senior', 'wordlist', 'required1', 'U3', 'observe a festival', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'range', 'n.', '/reɪndʒ/', '一系列;范围', 'We organised a range of activities for Grandma''s party.', '我们为奶奶的派对安排了一系列活动。', 'Family Matters', 35, 0, 'senior', 'wordlist', 'required1', 'U3', 'a range of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'event', 'n.', '/ɪˈvent/', '活动;事件', 'The birthday party was a happy family event for us all.', '生日派对对我们大家来说是一次快乐的家庭活动。', 'Family Matters', 36, 0, 'senior', 'wordlist', 'required1', 'U3', 'a family event', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'apologise', 'v.', '/əˈpɒlədʒaɪz/', '道歉', 'Mum apologised for missing my school performance.', '妈妈为错过我的校园演出而道歉。', 'Family Matters', 37, 0, 'senior', 'wordlist', 'required1', 'U3', 'apologise for', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'impact', 'n.', '/ˈɪmpækt/', '作用;影响', 'A few kind words can have a big impact on family life.', '几句善意的话能对家庭生活产生很大影响。', 'Family Matters', 38, 0, 'senior', 'wordlist', 'required1', 'U3', 'a big impact', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'strength', 'n.', '/streŋθ/', '强烈程度;力量', 'The strength of an apology depends on the words you choose.', '道歉的力度取决于你所选择的措辞。', 'Family Matters', 39, 0, 'senior', 'wordlist', 'required1', 'U3', 'the strength of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'admire', 'v.', '/ədˈmaɪə/', '钦佩;赞美;羡慕', 'I really admire my elder sister for her hard work.', '我非常钦佩姐姐的勤奋努力。', 'Family Matters', 40, 0, 'senior', 'wordlist', 'required1', 'U3', 'admire someone', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'judge', 'v.', '/dʒʌdʒ/', '判断;评判;认为', 'We should not judge our parents too quickly.', '我们不应过快地评判自己的父母。', 'Family Matters', 41, 0, 'senior', 'wordlist', 'required1', 'U3', 'judge someone', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'settle', 'v.', '/ˈsetl/', '和解;解决;结束(争论)', 'Grandfather helped the family settle their argument.', '爷爷帮助这家人化解了争吵。', 'Family Matters', 42, 0, 'senior', 'wordlist', 'required1', 'U3', 'settle an argument', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'detail', 'n.', '/ˈdiːteɪl/', '细节;细微之处', 'Penny described every detail of the family holiday.', '彭妮描述了那次家庭假期的每一个细节。', 'Family Matters', 43, 0, 'senior', 'wordlist', 'required1', 'U3', 'every detail', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'contain', 'v.', '/kənˈteɪn/', '包含;含有', 'Her letter contained many warm family memories.', '她的信里包含着许多温暖的家庭回忆。', 'Family Matters', 44, 0, 'senior', 'wordlist', 'required1', 'U3', 'contain memories', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'summary', 'n.', '/ˈsʌməri/', '总结;概要', 'She gave a short summary of the family trip at dinner.', '晚饭时她简短地总结了这次家庭旅行。', 'Family Matters', 45, 0, 'senior', 'wordlist', 'required1', 'U3', 'a short summary', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'positive', 'adj.', '/ˈpɒzɪtɪv/', '积极的;好的;肯定的', 'Having a brother has been a positive force in my life.', '有个兄弟一直是我生命中一股积极的力量。', 'Family Matters', 46, 0, 'senior', 'wordlist', 'required1', 'U3', 'a positive force', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'despite', 'prep.', '/dɪˈspaɪt/', '尽管;虽然', 'Despite their argument, the family still loved one another.', '尽管发生了争吵,这家人仍然彼此相爱。', 'Family Matters', 47, 0, 'senior', 'wordlist', 'required1', 'U3', 'despite the argument', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'indeed', 'adv.', '/ɪnˈdiːd/', '确实;的确(用于强调)', 'Love is indeed a magical ingredient in any family.', '在任何一个家庭里,爱确实是一种神奇的成分。', 'Family Matters', 48, 0, 'senior', 'wordlist', 'required1', 'U3', 'indeed', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f1u3.01', '①一般现在时 vs 现在进行时', 'A2', 10, '外研社版必修第一册 U3 — 经常/反复发生(every day/usually/always/often/regularly)用一般现在时;此刻正在进行(right now/at the moment/Look!/Listen!/now/这一阵子临时性)用现在进行时。看时间标志词定形。', 1, 'required1', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f1u3.02', '②现在完成时 vs 一般过去时', 'A2', 10, '外研社版必修第一册 U3 — 与现在相连、动作持续或影响到现在(since/for/already/yet/just/ever/never/recently/so far)用现在完成时;指过去某个确定时间、与现在脱节(yesterday/ago/last.../in+年份/when I was)用一般过去时。', 2, 'required1', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f1u3.03', '③一般过去时 vs 过去完成时 / 过去进行时', 'A2', 10, '外研社版必修第一册 U3 — 过去先发生(过去的过去:by the time/before/...had taken then)用过去完成时;过去某刻正在进行、作背景(while/when 被打断/as)用过去进行时;按时间先后依次发生的动作用一般过去时。', 3, 'required1', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.01'), '"Listen! Grandpa ____ (tell) a story about his childhood right now."', 'is telling', 'tells', 'told', 'has told', 'A', 'Listen! 和 right now 表此刻正在进行 → 现在进行时。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.01'), '"Look! Mum ____ (jog) in the park at the moment."', 'jogs', 'is jogging', 'jogged', 'has jogged', 'B', 'Look! 与 at the moment 表此刻进行 → 现在进行时。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.01'), '"Be quiet — Dad ____ (record) his voice in the studio now."', 'records', 'recorded', 'is recording', 'has recorded', 'C', 'now 加上''安静''的语境表此刻进行 → 现在进行时。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.01'), '"My sister ____ (study) for her exams at the moment."', 'studies', 'studied', 'has studied', 'is studying', 'D', 'at the moment 表此刻进行 → 现在进行时。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.01'), '"Look! The whole family ____ (play) chess together now."', 'is playing', 'plays', 'played', 'has played', 'A', 'Look! 与 now 表此刻进行 → 现在进行时(family 作整体,谓语单数)。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.01'), '"Don''t disturb him; my brother ____ (practise) the guitar right now."', 'practises', 'is practising', 'practised', 'has practised', 'B', 'right now 表此刻进行 → 现在进行时。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.01'), '"At the moment, Grandma ____ (make) a scarf for me."', 'makes', 'made', 'is making', 'has made', 'C', 'At the moment 表此刻进行 → 现在进行时。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.01'), '"Look! Dad ____ (hang) up the family photos now."', 'hangs', 'hung', 'has hung', 'is hanging', 'D', 'Look! 与 now 表此刻进行 → 现在进行时。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.01'), '"Listen! The children ____ (argue) about the TV again right now."', 'are arguing', 'argue', 'argued', 'have argued', 'A', 'Listen! 与 right now 表此刻进行 → 现在进行时(复数 children 用 are)。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.01'), '"We ____ (plan) a surprise party for Grandma this week."', 'plan', 'are planning', 'planned', 'have planned', 'B', 'this week 指当下这一阵子临时进行 → 现在进行时。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.01'), '"Mum ____ (jog) every morning to keep fit."', 'is jogging', 'jogged', 'jogs', 'has jogged', 'C', 'every morning 表经常性习惯 → 一般现在时。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.01'), '"We ____ (visit) Grandma every Sunday afternoon."', 'are visiting', 'visited', 'have visited', 'visit', 'D', 'every Sunday 表反复习惯 → 一般现在时。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.01'), '"Dad usually ____ (work) in the court during the week."', 'works', 'is working', 'worked', 'has worked', 'A', 'usually 表习惯 → 一般现在时。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.01'), '"My brother always ____ (focus) on his music after school."', 'is focusing', 'focuses', 'focused', 'has focused', 'B', 'always 表经常 → 一般现在时。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.01'), '"Grandpa ____ (play) chess with my father every Friday night."', 'is playing', 'played', 'plays', 'has played', 'C', 'every Friday night 表习惯 → 一般现在时。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.01'), '"Our family ____ (have) dinner together every evening."', 'is having', 'had', 'have had', 'has', 'D', 'every evening 表习惯,family 作整体用单数 → 一般现在时 has。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.01'), '"I ____ (respect) my parents'' opinions, even when I disagree."', 'respect', 'am respecting', 'respected', 'have respected', 'A', '表一贯态度(状态动词)→ 一般现在时。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.01'), '"She often ____ (chat) with her sister on the phone."', 'is chatting', 'chats', 'chatted', 'has chatted', 'B', 'often 表经常 → 一般现在时。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.01'), '"My grandparents ____ (observe) this festival regularly every May."', 'are observing', 'observed', 'observe', 'have observed', 'C', 'regularly every May 表习惯 → 一般现在时(复数主语用原形)。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.01'), '"Dad ____ (drive) us to school every day before work."', 'is driving', 'drove', 'has driven', 'drives', 'D', 'every day 表习惯 → 一般现在时。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.02'), '"Dad ____ (change) quite a bit since we last saw him."', 'has changed', 'changed', 'changes', 'is changing', 'A', 'since we last saw him 强调对现在的影响 → 现在完成时。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.02'), '"I ____ (finish) the guest list for the party already."', 'finished', 'have finished', 'finish', 'had finished', 'B', 'already 与现在相连 → 现在完成时。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.02'), '"Grandma ____ (live) in this house for over thirty years."', 'lived', 'lives', 'has lived', 'is living', 'C', 'for over thirty years 表持续到现在 → 现在完成时。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.02'), '"We ____ (not see) our cousins since last summer."', 'didn''t see', 'don''t see', 'aren''t seeing', 'haven''t seen', 'D', 'since last summer 表到现在为止 → 现在完成时。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.02'), '"My brother ____ (decide) to focus on his band already."', 'has decided', 'decided', 'decides', 'had decided', 'A', 'already 与现在相连 → 现在完成时。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.02'), '"Mum ____ (be) very busy with work recently."', 'was', 'has been', 'is', 'will be', 'B', 'recently 表延续到现在 → 现在完成时。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.02'), '"So far this week, Dad ____ (cook) dinner for us three times."', 'cooked', 'cooks', 'has cooked', 'had cooked', 'C', 'So far 表到目前为止 → 现在完成时。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.02'), '"That is the kindest thing my dad ____ (ever do) for me."', 'ever did', 'ever does', 'had ever done', 'has ever done', 'D', '最高级 + ever 表到现在为止 → 现在完成时。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.02'), '"My grandparents ____ (be) married for fifty years now."', 'have been', 'were', 'are', 'had been', 'A', 'for fifty years now 表持续到现在 → 现在完成时。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.02'), '"Penny ____ (grow) a lot since that photo was taken."', 'grew', 'has grown', 'grows', 'is growing', 'B', 'since that photo was taken 表对现在的影响 → 现在完成时。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.02'), '"Grandma ____ (call) us yesterday to say hello."', 'has called', 'calls', 'called', 'had called', 'C', 'yesterday 是确定的过去时间 → 一般过去时。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.02'), '"We ____ (have) a fantastic holiday in Beidaihe last summer."', 'have had', 'have', 'has had', 'had', 'D', 'last summer 是确定的过去时间 → 一般过去时。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.02'), '"Dad ____ (show) me an old photo a moment ago."', 'showed', 'has shown', 'shows', 'had shown', 'A', 'a moment ago 表过去某刻 → 一般过去时。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.02'), '"When I was young, I ____ (have) cute rosy cheeks."', 'have had', 'had', 'have', 'has had', 'B', 'When I was young 指过去时段 → 一般过去时。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.02'), '"My parents ____ (get) married in 2005."', 'have got', 'get', 'got', 'had got', 'C', 'in 2005 是确定过去时间 → 一般过去时。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.02'), '"I ____ (cook) scrambled eggs for Mum on her birthday last year."', 'have cooked', 'cook', 'had cooked', 'cooked', 'D', 'last year 是确定过去时间 → 一般过去时。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.02'), '"Grandpa ____ (teach) my father chess many years ago."', 'taught', 'has taught', 'teaches', 'had taught', 'A', 'many years ago 表过去 → 一般过去时。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.02'), '"We ____ (stay) at the same campsite ten years ago."', 'have stayed', 'stayed', 'stay', 'had stayed', 'B', 'ten years ago 表过去 → 一般过去时。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.02'), '"Dad ____ (be) quite thin and pale in his thirties."', 'has been', 'is', 'was', 'had been', 'C', 'in his thirties 指过去时段 → 一般过去时。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.02'), '"My sister ____ (win) a medal at a school race last week."', 'has won', 'wins', 'had won', 'won', 'D', 'last week 是确定过去时间 → 一般过去时。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.03'), '"By the time we arrived, Grandma ____ (prepare) dinner already."', 'had prepared', 'prepared', 'prepares', 'has prepared', 'A', 'By the time we arrived 之前已完成 → 过去完成时(过去的过去)。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.03'), '"Dad showed me a photo that we ____ (take) ten years before."', 'took', 'had taken', 'take', 'have taken', 'B', 'ten years before(早于过去拍照那刻)→ 过去完成时。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.03'), '"Before he joined the band, my brother ____ (not perform) in public."', 'did not perform', 'does not perform', 'had not performed', 'has not performed', 'C', 'Before he joined 之前的状态 → 过去完成时。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.03'), '"When I got to the kitchen, I realised I ____ (burn) the eggs."', 'burnt', 'burns', 'have burnt', 'had burnt', 'D', '烧糊发生在''意识到''之前 → 过去完成时。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.03'), '"By the time Mum sat down, she ____ (finish) all the housework."', 'had finished', 'finished', 'finishes', 'has finished', 'A', 'By the time Mum sat down 之前完成 → 过去完成时。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.03'), '"I wanted to thank Grandpa, but he ____ (leave) already."', 'left', 'had left', 'leaves', 'has left', 'B', '离开早于''想感谢''那刻 → 过去完成时。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.03'), '"By the time the guests arrived, we ____ (decorate) the whole room."', 'decorated', 'decorate', 'had decorated', 'have decorated', 'C', 'By the time the guests arrived 之前完成 → 过去完成时。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.03'), '"Mum told me that she ____ (meet) my father at university."', 'met', 'meets', 'has met', 'had met', 'D', '相遇早于''告诉''那刻(过去的过去)→ 过去完成时。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.03'), '"I ____ (tidy) my room when I found an old photo in a notebook."', 'was tidying', 'tidied', 'had tidied', 'tidies', 'A', '整理房间是被''发现''打断的背景动作 → 过去进行时。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.03'), '"While Mum ____ (cook), I quietly set the table for dinner."', 'cooked', 'was cooking', 'had cooked', 'cooks', 'B', 'While 引导的背景动作正在进行 → 过去进行时。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.03'), '"When Dad came in, the children ____ (play) chess at the table."', 'played', 'had played', 'were playing', 'play', 'C', 'Dad 进来时正在下棋(背景)→ 过去进行时。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.03'), '"As I ____ (look) at the photo, the lovely memory came back to me."', 'looked', 'had looked', 'looks', 'was looking', 'D', 'As 引导的动作正在进行作背景 → 过去进行时。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.03'), '"Grandfather and Father ____ (play) chess when the son came in."', 'were playing', 'played', 'had played', 'play', 'A', '儿子进来时两人正在下棋(背景)→ 过去进行时。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.03'), '"While we ____ (camp) in Beidaihe, it suddenly started to rain."', 'camped', 'were camping', 'had camped', 'camp', 'B', 'While 引导的背景动作正在进行,被''下雨''打断 → 过去进行时。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.03'), '"Mum ____ (talk) on the phone when I got home from school."', 'talked', 'had talked', 'was talking', 'talks', 'C', '我到家时她正在打电话(背景)→ 过去进行时。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.03'), '"Yesterday my brother ____ (tell) Dad about his dream of a music career."', 'had told', 'tells', 'was telling', 'told', 'D', 'yesterday 表过去某刻发生的单一动作 → 一般过去时。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.03'), '"Grandpa ____ (step) between them and then raised his voice."', 'stepped', 'had stepped', 'steps', 'was stepping', 'A', 'and then 表依次发生的动作 → 一般过去时。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.03'), '"The son ____ (enter) the room and sat down at the table."', 'had entered', 'entered', 'enters', 'was entering', 'B', 'and 连接的两个先后动作 → 一般过去时。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.03'), '"When the curtain fell, the whole family ____ (clap) loudly."', 'had clapped', 'claps', 'clapped', 'were clapping', 'C', '幕落''后''紧接的反应动作 → 一般过去时。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required1' AND unit='U3' AND code='f1u3.03'), '"After the argument, the family finally ____ (settle) their differences."', 'had settled', 'settles', 'were settling', 'settled', 'D', 'After the argument 之后发生的动作 → 一般过去时。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Dream and a Gap', 'One Friday evening, the son walked nervously up to his father and said they needed to talk. He had decided not to go to university. Instead, he wanted to focus on his band and have a career in music. The father raised his voice in surprise. He had always assumed that his son would become a lawyer, just like himself, because lawyers help people and are respected by others. But the son was not interested in law. He wanted to work in a music studio, not in a court. Luckily, the grandfather was there to calm everyone down. He reminded the father that, years ago, he too had once dreamed of being a footballer. In the end, his own father had only advised him to think carefully, and he had found a job that suited his talents. So the grandfather gently suggested that the son might study at university and play music at the same time, keeping two options open for the future.', '记叙·代沟与梦想', 163, '[{"q":"Why was the father surprised by his son''s decision?","answer":"A","options":["He had taken it for granted that his son would study law.","He wanted his son to play in a band.","He had never met a lawyer before.","He had already agreed to the music career."],"explanation":"原文 ''He had always assumed that his son would become a lawyer'' 的转述。"},{"q":"What did the grandfather remind the father about?","answer":"B","options":["That lawyers earn a lot of money.","That he himself had once had a dream of his own.","That music is a waste of time.","That the son should leave home."],"explanation":"原文 grandfather 提醒父亲''years ago, he too had once dreamed of being a footballer''(中段)。"},{"q":"What solution did the grandfather suggest?","answer":"A","options":["Doing both university and music together.","Giving up music for good.","Leaving university at once.","Becoming a footballer instead."],"explanation":"末句 ''study at university and play music at the same time'' 的转述。"}]'::jsonb, '[{"word":"career","cn":"职业"},{"word":"assume","cn":"认为;假定"},{"word":"studio","cn":"录音室"},{"word":"option","cn":"选择"}]'::jsonb, 2, 'required1', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Burnt Eggs', 'While I was tidying my room one afternoon, I found an old photo hidden inside a notebook, and a lovely memory came back to me. It was my mother''s birthday ten years ago, and I had decided to surprise her with home-made scrambled eggs. I woke up really early and tiptoed to the kitchen so that nobody would hear me. I had never cooked anything before that morning, so I simply tried to copy the way Mum usually did it. Somehow, though, the eggs ended up burnt and black. I was just about to throw everything away when my mother walked in. Feeling rather sad, I showed her the eggs and explained what had gone wrong. To my great surprise, she tasted them and said they were not bad at all. We both started laughing and ended up eating every bit. Now I understand that love is indeed a magical ingredient, and this weekend I will cook for her again.', '记叙·一段家庭回忆', 160, '[{"q":"What brought the writer''s memory back?","answer":"B","options":["An old photo found while cleaning the room.","A birthday card from Mum.","A smell coming from the kitchen.","A phone call from a friend."],"explanation":"本题答案对应原文''found an old photo… a lovely memory came back''的转述(改写为''cleaning the room'')。"},{"q":"How did the eggs turn out that morning?","answer":"C","options":["They tasted perfect.","They got burnt and black.","They were never finished.","Mum cooked them instead."],"explanation":"原文 ''the eggs ended up burnt and black''(中段)的转述。"},{"q":"How did the mother react to the burnt eggs?","answer":"D","options":["She was angry and left.","She threw them away at once.","She asked the writer never to cook again.","She reassured the writer and finished the eggs herself."],"explanation":"原文 ''she tasted them and said they were not bad… ate every bit'' 的转述。"}]'::jsonb, '[{"word":"memory","cn":"回忆"},{"word":"indeed","cn":"确实"}]'::jsonb, 2, 'required1', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'How Dad Has Changed', 'After our family holiday, I looked again at a photo we had taken at the same campsite ten years before, and I could not believe how much my dad had changed. Back in his thirties, he was quite thin and pale, and he had thick red hair. Nowadays he is well-built and tanned from working outdoors. He has always had a strong square jaw, but recently he has grown a beard. Strangely, his beard is still red, even though the hair on his head is slowly turning grey. My mother, on the other hand, looks almost the same as before. She still has smooth skin and straight black hair, and years of jogging every morning have kept her slim and fit. As for me, I still have light skin and dark hair, but these days I usually wear it in a ponytail, since it has grown much longer. Mum says I once had rosy cheeks, though now I have a few freckles instead.', '说明·外貌的变化', 163, '[{"q":"What did the writer''s dad look like in his thirties?","answer":"A","options":["Thin, pale and red-haired.","Well-built and tanned.","Grey-bearded and tall.","Short with black hair."],"explanation":"原文 ''he was quite thin and pale, and he had thick red hair'' 的转述。"},{"q":"Why does the writer''s mother stay slim and fit?","answer":"B","options":["Because she eats very little.","Because she goes jogging every morning.","Because she is still young.","Because she works outdoors."],"explanation":"原文 ''years of jogging every morning have kept her slim and fit''(中段)的转述。"},{"q":"How has the writer''s own appearance changed?","answer":"C","options":["The hair has turned grey.","The skin has become darker.","The hair is longer and worn in a ponytail.","The cheeks are rosier than before."],"explanation":"原文 ''wear it in a ponytail, since it has grown much longer'' 的转述。"}]'::jsonb, '[{"word":"jaw","cn":"下巴"},{"word":"beard","cn":"胡须"},{"word":"slim","cn":"苗条的"},{"word":"cheek","cn":"脸颊"}]'::jsonb, 2, 'required1', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Brother First', 'It was the final race of a world series in Mexico. With only a few hundred metres left, Alistair Brownlee was in third place, while his younger brother Jonny was leading. As Alistair pushed himself forward in the burning heat, he saw Jonny about to fall onto the track. In that moment he had to make a choice: love for his brother, or a chance to win. For Alistair the answer was clear. He ran to Jonny, caught him, and started pulling him towards the finish line. Then he pushed his brother across the line ahead of himself. The move put Jonny in second place and left Alistair in third. Watched by millions, the ending divided opinions: some thought the brothers should be praised, while others felt they should be disqualified. But Alistair did not care about a medal. He later explained that their mother would not have been happy if he had left Jonny behind. At that moment, he was simply a brother.', '记叙·兄弟之爱', 164, '[{"q":"What difficult choice did Alistair face during the race?","answer":"D","options":["Whether to run faster or stop completely.","Whether to change his shoes or not.","Whether to start the race again.","Whether to help his brother or try to win."],"explanation":"原文 ''love for his brother, or a chance to win'' 的转述。"},{"q":"What did Alistair actually do near the finish line?","answer":"A","options":["He pulled Jonny along and let him finish ahead.","He ran past his brother to win.","He stopped and gave up the race.","He called for the doctors."],"explanation":"原文 ''pushed his brother across the line ahead of himself''(中段)的转述。"},{"q":"Why did Alistair say he made that choice?","answer":"B","options":["Because he disliked racing.","Because their mother would have been unhappy otherwise.","Because the rules forced him to.","Because he was sure to lose anyway."],"explanation":"原文 ''their mother would not have been happy if he had left Jonny behind'' 的转述。"}]'::jsonb, '[{"word":"track","cn":"跑道"},{"word":"medal","cn":"奖牌"},{"word":"disqualify","cn":"取消资格"}]'::jsonb, 2, 'required1', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Day for Families', 'Did you know that there is a special day just for families? The International Day of Families was set by the United Nations back in 1993, and it is held on the fifteenth of May every year. The main aim of the day is to celebrate how important families are to people everywhere. It also tries to help people understand the many issues that families face in modern life, such as health, work and care for the old. Each year the day has a different theme, so the focus changes from one year to the next. Across the whole nation, and indeed around the world, a wide range of events are organised to mark it. Some are held in small towns, while others take place at the national level. Schools, libraries and local groups all join in with talks, shows and games. Through these activities, families are reminded to spend more time together and to value the people closest to them.', '说明·国际家庭日', 161, '[{"q":"When is the International Day of Families held each year?","answer":"C","options":["On the first day of the year.","Whenever a town decides.","Each year in the middle of May.","Only in the year 1993."],"explanation":"原文 ''held on the fifteenth of May every year'' 的转述。"},{"q":"What is the main aim of the day?","answer":"D","options":["To sell family products.","To start new schools.","To stop families travelling.","To show people that families truly matter."],"explanation":"原文 ''celebrate how important families are to people everywhere''(中段)的转述。"},{"q":"How is the day marked around the world?","answer":"A","options":["Through many kinds of events at different levels.","By closing all the shops.","By a single official meeting.","By giving everyone a holiday from school."],"explanation":"原文 ''a wide range of events are organised… small towns… national level'' 的转述。"}]'::jsonb, '[{"word":"nation","cn":"国家"},{"word":"theme","cn":"主题"},{"word":"range","cn":"一系列"},{"word":"issue","cn":"议题"}]'::jsonb, 2, 'required1', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Saying Sorry to Mum', 'Today there was an important school event, but my mother missed it, and I felt really hurt. Later, on the phone, she said sorry and explained that she had been busy at work because a colleague was away. I could tell from her voice that she truly meant it. I know that she has been under a lot of pressure recently, and I understand that, yet I do not like seeing her so tired and worried all the time. I think she really needs to take some time off work to rest. So I decided to tell her how I felt, instead of keeping my worries to myself. To make up for the missed event, we have planned a trip together next week. We will go camping, share a big meal, and most importantly find time to talk properly. Mum says that placing stress on certain words can make an apology stronger, and her gentle ''I am truly sorry'' was more than enough for me.', '记叙·向家人道歉', 165, '[{"q":"Why did the mother miss the school event?","answer":"B","options":["She forgot the date completely.","She had to cover work for an absent colleague.","She was on a camping trip.","She did not think it was important."],"explanation":"原文 ''busy at work because a colleague was away'' 的转述。"},{"q":"How does the writer feel about the mother?","answer":"C","options":["Angry and unwilling to forgive her.","Glad that she stays away from home.","Worried about how tired she is.","Sure that she does not care."],"explanation":"原文 ''I do not like seeing her so tired and worried'' 的转述。"},{"q":"What did they plan in order to make up for it?","answer":"D","options":["To buy each other gifts.","To stop talking for a while.","To ask the colleague to apologise.","To go camping and spend time together."],"explanation":"原文 ''planned a trip… go camping… find time to talk'' 的转述。"}]'::jsonb, '[{"word":"apologise","cn":"道歉"},{"word":"stress","cn":"重音;强调"},{"word":"impact","cn":"影响"}]'::jsonb, 2, 'required1', 'U3', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U3', 'Getting Ready for Grandma''s Party', 'My mum called Grandma yesterday and (1)____ her to our house this Sunday. We are going to (2)____ her a big birthday party, so everyone needs to choose a (3)____. My brother Adam has decided to give her a new tea (4)____, because she loves drinking tea. My sister Sally is thinking of (5)____ a warm scarf for her by hand. Dad is (6)____ on the invitations, and he has already finished the guest (7)____. Mum says we still need to prepare the (8)____ and drinks for the day. Everyone in the family is (9)____ to help, and we are all very (10)____ about the surprise.', 106, 2, '[{"q":"1","answer":"A","options":["invited","cooked","ignored","judged"],"explanation":"invited her to our house 邀请她。"},{"q":"2","answer":"B","options":["sell","throw","lose","break"],"explanation":"throw a party 办派对。"},{"q":"3","answer":"C","options":["curtain","court","present","gap"],"explanation":"choose a present 选礼物。"},{"q":"4","answer":"D","options":["studio","beard","theme","set"],"explanation":"a tea set 一套茶具。"},{"q":"5","answer":"A","options":["making","eating","selling","losing"],"explanation":"thinking of making a scarf 考虑织围巾。"},{"q":"6","answer":"B","options":["sleeping","working","crying","leaving"],"explanation":"working on the invitations 在做请柬。"},{"q":"7","answer":"C","options":["noise","price","list","weather"],"explanation":"the guest list 宾客名单。"},{"q":"8","answer":"D","options":["music","homework","rain","food"],"explanation":"food and drinks 食物和饮料。"},{"q":"9","answer":"A","options":["happy","angry","afraid","sorry"],"explanation":"happy to help 乐意帮忙。"},{"q":"10","answer":"B","options":["bored","excited","tired","sad"],"explanation":"excited about the surprise 对惊喜很兴奋。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U3', 'A Talk with Dad', 'Last night I had a long (1)____ with my father about my future. For a long time he had simply (2)____ that I would become a lawyer like him. But I am far more (3)____ in music than in law. I told him that I wanted to (4)____ on my band after school. At first he was surprised and (5)____ my idea completely. Luckily, Grandpa helped to (6)____ the argument between us. He reminded Dad that everyone has a different (7)____. In the end, Dad agreed to (8)____ my choice, even though he still has a few (9)____. I feel very lucky to have such an (10)____ family.', 108, 2, '[{"q":"1","answer":"C","options":["court","beard","chat","medal"],"explanation":"had a long chat 长谈。"},{"q":"2","answer":"D","options":["cooked","jogged","clapped","assumed"],"explanation":"had assumed that 一直以为。"},{"q":"3","answer":"A","options":["interested","afraid","tired","sorry"],"explanation":"interested in music 对音乐感兴趣。"},{"q":"4","answer":"B","options":["sleep","focus","cry","sell"],"explanation":"focus on my band 专注于乐队。"},{"q":"5","answer":"C","options":["enjoyed","watched","ignored","washed"],"explanation":"ignored my idea 不理会我的想法。"},{"q":"6","answer":"D","options":["break","lose","throw","settle"],"explanation":"settle the argument 化解争吵。"},{"q":"7","answer":"A","options":["talent","curtain","court","gap"],"explanation":"a different talent 不同的天赋。"},{"q":"8","answer":"B","options":["ignore","respect","break","lose"],"explanation":"respect my choice 尊重我的选择。"},{"q":"9","answer":"C","options":["songs","prices","worries","shoes"],"explanation":"still has a few worries 仍有些担忧。"},{"q":"10","answer":"D","options":["angry","boring","sleepy","understanding"],"explanation":"an understanding family 善解人意的家庭。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U3', 'A Family Camping Trip', 'To make up for a busy month, our family (1)____ to go camping last weekend. We drove to a quiet (2)____ near a lake and put up our tent together. While Dad (3)____ a fire, Mum prepared a simple meal. The fresh air and the (4)____ of the pine trees made everyone feel relaxed. After dinner we sat around the fire and (5)____ stories about the past. Grandpa told us about the days when he was (6)____ and full of energy. We laughed so much that our (7)____ began to hurt. Most importantly, we had plenty of time to (8)____ properly and share our worries. Spending a whole day (9)____ brought us much closer. It was indeed a (10)____ family memory.', 121, 2, '[{"q":"1","answer":"A","options":["decided","sold","ignored","lost"],"explanation":"decided to go camping 决定去露营。"},{"q":"2","answer":"B","options":["curtain","spot","beard","court"],"explanation":"a quiet spot 安静的地方。"},{"q":"3","answer":"C","options":["ate","sold","built","threw"],"explanation":"built a fire 生火。"},{"q":"4","answer":"D","options":["price","list","medal","smell"],"explanation":"the smell of the pine trees 松树的气味。"},{"q":"5","answer":"A","options":["shared","sold","burnt","washed"],"explanation":"shared stories 分享故事。"},{"q":"6","answer":"B","options":["sorry","young","afraid","boring"],"explanation":"when he was young 他年轻时。"},{"q":"7","answer":"C","options":["curtains","courts","cheeks","medals"],"explanation":"our cheeks began to hurt 笑得脸颊发酸。"},{"q":"8","answer":"D","options":["sleep","drive","sell","talk"],"explanation":"time to talk 谈心的时间。"},{"q":"9","answer":"A","options":["together","quietly","quickly","loudly"],"explanation":"a whole day together 一起度过一整天。"},{"q":"10","answer":"B","options":["boring","lovely","terrible","sad"],"explanation":"a lovely family memory 美好的家庭回忆。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U3', 'My Grandfather', 'My grandfather is the kindest (1)____ in our whole family. He has a gentle (2)____ and almost never loses his temper. Every Friday evening he (3)____ chess with my father at the kitchen table. People say there is often a (4)____ between the old and the young, but I never feel it with him. Whenever I have a problem, I can always (5)____ to him for advice. He listens carefully and never (6)____ me, even when my ideas sound silly. He has (7)____ in this house for over forty years, so he knows every family story. Nowadays he walks more slowly, but his mind is still very (8)____. I (9)____ him more than anyone else, and I hope to be as wise as him when I grow (10)____.', 128, 2, '[{"q":"1","answer":"C","options":["court","medal","person","beard"],"explanation":"the kindest person 最善良的人。"},{"q":"2","answer":"D","options":["studio","gap","theme","character"],"explanation":"a gentle character 温和的性格。"},{"q":"3","answer":"A","options":["plays","sells","burns","washes"],"explanation":"plays chess 下棋。"},{"q":"4","answer":"B","options":["curtain","gap","court","list"],"explanation":"a gap between the old and the young 代沟。"},{"q":"5","answer":"C","options":["sell","burn","turn","lose"],"explanation":"turn to him for advice 向他求助。"},{"q":"6","answer":"D","options":["sells","cooks","jogs","judges"],"explanation":"never judges me 从不评判我。"},{"q":"7","answer":"A","options":["lived","sold","burnt","washed"],"explanation":"has lived in this house 住在这房子里。"},{"q":"8","answer":"B","options":["sorry","sharp","afraid","slim"],"explanation":"his mind is sharp 头脑敏锐。"},{"q":"9","answer":"C","options":["ignore","break","admire","lose"],"explanation":"admire him 钦佩他。"},{"q":"10","answer":"D","options":["down","in","off","up"],"explanation":"grow up 长大。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U3', 'Saying Sorry', 'Last week my mum (1)____ an important school show of mine because of her work. I felt hurt and could not (2)____ my disappointment. Later she phoned me to (3)____ and explained that a colleague had been away. I could hear from her voice that she was (4)____ sorry. I know she has been under a lot of (5)____ recently, so I tried to understand. Instead of staying angry, I decided to (6)____ her how I really felt. To make (7)____ for it, we planned a special day out together. Mum told me that (8)____ stress on certain words can make an apology much stronger. Her gentle words had a big (9)____ on me. In the end, saying sorry honestly brought us closer than (10)____.', 125, 2, '[{"q":"1","answer":"A","options":["missed","sold","built","jogged"],"explanation":"missed an important show 错过演出。"},{"q":"2","answer":"B","options":["sell","hide","drive","wash"],"explanation":"hide my disappointment 掩饰失望。"},{"q":"3","answer":"C","options":["sell","cook","apologise","drive"],"explanation":"phoned to apologise 打电话道歉。"},{"q":"4","answer":"D","options":["hardly","never","rarely","truly"],"explanation":"truly sorry 真心抱歉。"},{"q":"5","answer":"A","options":["pressure","curtain","medal","beard"],"explanation":"under a lot of pressure 压力很大。"},{"q":"6","answer":"B","options":["sell","tell","burn","lose"],"explanation":"tell her how I felt 告诉她感受。"},{"q":"7","answer":"C","options":["down","in","up","off"],"explanation":"make up for it 弥补。"},{"q":"8","answer":"D","options":["eating","selling","washing","placing"],"explanation":"placing stress on words 在词上重读。"},{"q":"9","answer":"A","options":["impact","noise","price","list"],"explanation":"had a big impact on me 对我影响很大。"},{"q":"10","answer":"B","options":["never","before","often","always"],"explanation":"closer than before 比从前更近。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required1', 'U3', 'Why I Admire My Sister', 'My elder sister is the person I (1)____ most in our family. She is (2)____ studying at a university in another city, so we do not see her often. Even so, she calls home (3)____ every week to chat with us. She has always been very (4)____ and helps our parents whenever she can. When I was younger, she would (5)____ me with my homework every evening. She never (6)____ my silly questions, no matter how busy she was. People say she has a real (7)____ for music, and she now plays in a college band. Her hard work has had a positive (8)____ on me. (9)____ the long distance between us, we stay very close. I really hope to be as kind and clever as her one (10)____.', 129, 2, '[{"q":"1","answer":"C","options":["ignore","sell","admire","burn"],"explanation":"the person I admire most 我最钦佩的人。"},{"q":"2","answer":"D","options":["hardly","never","rarely","currently"],"explanation":"is currently studying 目前在学习。"},{"q":"3","answer":"A","options":["regularly","loudly","quickly","sadly"],"explanation":"calls home regularly 定期打电话。"},{"q":"4","answer":"B","options":["afraid","responsible","bored","slim"],"explanation":"very responsible 很有责任心。"},{"q":"5","answer":"C","options":["sell","burn","help","lose"],"explanation":"help me with my homework 帮我做作业。"},{"q":"6","answer":"D","options":["sold","cooked","jogged","ignored"],"explanation":"never ignored my questions 从不忽视我的问题。"},{"q":"7","answer":"A","options":["talent","curtain","court","gap"],"explanation":"a real talent for music 音乐天赋。"},{"q":"8","answer":"B","options":["noise","impact","price","list"],"explanation":"a positive impact on me 对我有积极影响。"},{"q":"9","answer":"C","options":["Because","Until","Despite","Unless"],"explanation":"Despite the long distance 尽管距离远(后接名词短语)。"},{"q":"10","answer":"D","options":["curtain","medal","court","day"],"explanation":"one day 总有一天。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·对话 Planning Grandma''s Party', '外研社版必修第一册 U3 · dialogue', 3, 'Mum: Children, come here. I have some exciting news to tell you.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·短文 The International Day of Families', '外研社版必修第一册 U3 · passage', 2, 'Did you know there is a special day just for families?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·对话 A Career in Music', '外研社版必修第一册 U3 · dialogue', 3, 'Son: Dad, can we talk? I''ve made an important decision.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·短文 How My Dad Has Changed', '外研社版必修第一册 U3 · passage', 2, 'Let me tell you how much my dad has changed over the years.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·对话 Mum''s Apology', '外研社版必修第一册 U3 · dialogue', 3, 'Mum: I''m so sorry I missed your school show today. I feel terrible about it.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U3 听力·短文 A Tip on Saying Sorry', '外研社版必修第一册 U3 · passage', 2, 'Here is a useful tip about saying sorry to your family.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Write about a Family Memory(写一段家庭回忆)', 'A Family Memory I Treasure', '假设你叫李华。请用英语写一篇约80词的短文,记叙一段难忘的家庭回忆,内容包括:① 是什么勾起了这段回忆(时间/人物/地点);② 当时发生了什么事;③ 为什么这段回忆对你特别或难忘。注意:回忆部分用过去时态(一般过去/过去进行/过去完成),恰当使用时间标志词。', 'Suppose you are Li Hua. Write a short passage (about 80 words) about a family memory you treasure, including: 1) what brought the memory back (when / who / where); 2) what happened at that time; 3) why the memory is special or unforgettable to you. Note: use past tenses for the memory itself and link it to the present at the end.', '["什么勾起回忆(While I was …, I found … and a memory came back)","当时发生了什么(过去时叙事:I had decided … / Mum was …)","为什么难忘(I learnt that … / It is special because …)","时态准确:回忆用过去时,点题句用现在/将来"]'::jsonb, 70, 100, 'While I was tidying my room last weekend, I found an old photo and a lovely memory came back to me. It was my mother''s birthday ten years ago, and I had decided to surprise her with home-made eggs. I woke up early and tiptoed to the kitchen, but somehow the eggs got burnt. Just as I was about to throw them away, Mum walked in, tasted them and smiled. We laughed and ate them all. That day taught me that love is indeed a magical ingredient, and I still treasure it today.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["While I was tidying my room, a lovely memory came back to me.","It was my mother''s birthday ten years ago, and I had decided to surprise her.","Just as I was about to throw the eggs away, Mum walked in and smiled.","That day taught me that love is indeed a magical ingredient."]'::jsonb, '[{"wrong":"Yesterday I have found an old photo.","correct":"Yesterday I found an old photo.","note":"yesterday 是确定过去时间,用一般过去时,不用现在完成时。"},{"wrong":"While I tidied my room, I found a photo.","correct":"While I was tidying my room, I found a photo.","note":"while 引导的背景动作正在进行,用过去进行时。"},{"wrong":"I decided to surprise her before she woke up, so I cooked already.","correct":"I had decided to surprise her before she woke up.","note":"早于过去某动作发生,用过去完成时。"}]'::jsonb, '【家庭回忆记叙结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required1', 'U3', '{"title":"时态复习·一般/进行/完成(现在与过去)速查","intro":"时态看两件事:时间(现在/过去)和状态(经常做/正在做/已完成)。判断口诀:先找句中的时间标志词,再据它定时态——标志词决定唯一答案。","table":{"headers":["时态","用法 / 时间标志词 / 例句"],"rows":[["一般现在时","经常/反复:every day, usually, always, often, regularly — Mum jogs every morning."],["现在进行时","此刻正在:right now, at the moment, Look!, Listen!, now — Look! Dad is growing a beard now."],["现在完成时","持续/影响到现在:since, for, already, yet, just, ever, never, recently, so far — Dad has changed since we last met."],["一般过去时","过去确定时间:yesterday, ago, last…, in 2005, when I was young — Grandma called us yesterday."],["过去完成时","过去的过去:by the time, before, …had taken then — By the time we arrived, she had cooked dinner."],["过去进行时","过去某刻正在(作背景):while, when(被打断), as — While Mum was cooking, I set the table."]]},"specialRules":[{"rule":"since/for/already/yet/just → 现在完成时","mark":"I have just finished the guest list."},{"rule":"yesterday/ago/last…/in+年份 → 一般过去时(不用完成时)","mark":"We had a holiday last summer.(× have had)"},{"rule":"by the time + 过去句 → 主句用过去完成时","mark":"By the time he came, we had left."},{"rule":"while / when 被打断 → 背景动作用过去进行时","mark":"I was tidying my room when I found the photo."}],"why":["时态本质是''什么时候+什么状态'';时间标志词把范围锁死,所以一旦看到 since 就排除一般过去时、看到 yesterday 就排除现在完成时,答案自然唯一。"],"gaokaoPoints":["现在完成时 vs 一般过去时(since/for/already vs yesterday/ago)是语法填空与改错高频点。","过去完成时强调''过去的过去'';while/when 引导的背景常用过去进行时;family/记叙文里大量出现。"],"examVsReal":[{"exam":"I have just finished my homework.(考试/书面)","real":"I just finished my homework.(美式口语)","note":"考试里 just + 现在完成;美式口语常用一般过去 + just。"},{"exam":"By the time he arrived, we had eaten.(考试)","real":"By the time he arrived, we''d already eaten.","note":"口语多用缩写 ''d 并加 already,意思相同。"}]}'::jsonb, 'fltrp');
